insert into public.planned_releases (version, theme, items, sort) values ('0.1.1', 'Fixes and housekeeping', array['Re-run the engine benchmark against 0.1.0 and publish the results', 'Profile memory per entry and single-key writes, and fix what the profile shows']::text[], 10)
  on conflict (version) do nothing;
insert into public.planned_releases (version, theme, items, sort) values ('0.2.0', 'React parity', array['useQueries and useIsFetching', 'Persister and offline mutation queue', 'Real-browser and hydration benchmarks']::text[], 20)
  on conflict (version) do nothing;
insert into public.planned_releases (version, theme, items, sort) values ('0.3.0', 'Protocol completeness', array['GraphQL subscriptions, uploads and persisted queries', 'tRPC subscriptions', 'Live GraphQL demo, remote-schema caching and split output per tag']::text[], 30)
  on conflict (version) do nothing;
insert into public.planned_releases (version, theme, items, sort) values ('0.4.0', 'Reach', array['Vue adapter, then Svelte or Solid based on demand', 'Next.js and RSC integration', 'Per-request timeline and richer devtools']::text[], 40)
  on conflict (version) do nothing;

-- known limitations
insert into public.limitations (title, detail, workaround, area, sort) select 'No C# or .NET package', 'NyxAPI is TypeScript and JavaScript. It cannot be called from C# code such as .NET MAUI, WinForms or ASP.NET controllers.', 'Use it in the JavaScript front end of an ASP.NET site, or generate a C# client with NSwag, Kiota or Refit from the same OpenAPI document.', 'codegen', 10
  where not exists (select 1 from public.limitations where title = 'No C# or .NET package');
insert into public.limitations (title, detail, workaround, area, sort) select 'React only', 'The core runs anywhere, but the only UI adapter is React.', 'Use the core directly (QueryObserver and subscribe) in other frameworks.', 'react', 20
  where not exists (select 1 from public.limitations where title = 'React only');
insert into public.limitations (title, detail, workaround, area, sort) select 'No useQueries or useIsFetching', 'Running a dynamic list of queries in one hook, and a global fetching indicator hook, are not available yet.', 'Use queryClient.isFetching() and subscribeCache(), or one useQuery per component.', 'react', 30
  where not exists (select 1 from public.limitations where title = 'No useQueries or useIsFetching');
insert into public.limitations (title, detail, workaround, area, sort) select 'No persistence or offline mutation queue', 'The cache lives in memory. Paused fetches resume on reconnect, but queued mutations are not saved.', 'Use dehydrate and hydrate with your own storage.', 'core', 40
  where not exists (select 1 from public.limitations where title = 'No persistence or offline mutation queue');
insert into public.limitations (title, detail, workaround, area, sort) select 'GraphQL subscriptions, uploads and persisted queries', 'Subscriptions are skipped with a warning during generation. Multipart uploads and persisted queries are not generated.', 'Call those operations with your own client and share the cache through keys.', 'graphql', 50
  where not exists (select 1 from public.limitations where title = 'GraphQL subscriptions, uploads and persisted queries');
insert into public.limitations (title, detail, workaround, area, sort) select 'tRPC subscriptions', 'Queries and mutations are typed; subscriptions are not.', 'Use the tRPC client''s own subscription API.', 'trpc', 60
  where not exists (select 1 from public.limitations where title = 'tRPC subscriptions');
insert into public.limitations (title, detail, workaround, area, sort) select 'Cookie parameters are not generated', 'OpenAPI parameters with in: cookie are deliberately skipped, because browsers do not let scripts set a Cookie header.', 'Use the credentials client option for cookie sessions.', 'codegen', 70
  where not exists (select 1 from public.limitations where title = 'Cookie parameters are not generated');
insert into public.limitations (title, detail, workaround, area, sort) select 'Only successful responses are validated', 'With validation on, success bodies are checked against generated shapes. Error bodies and request bodies are not.', 'Validate request bodies in your own code or with a schema library before sending.', 'codegen', 80
  where not exists (select 1 from public.limitations where title = 'Only successful responses are validated');
insert into public.limitations (title, detail, workaround, area, sort) select 'Prefix filters that start with an object scan the whole cache', 'Filters whose first key element is a primitive use a fast bucket. Object-rooted or empty prefixes check every entry.', 'Keep keys primitive-first, which generated keys already are.', 'performance', 90
  where not exists (select 1 from public.limitations where title = 'Prefix filters that start with an object scan the whole cache');
insert into public.limitations (title, detail, workaround, area, sort) select 'Memory per cache entry is higher than TanStack Query', 'In the last benchmark run an entry retained about 1206 bytes against 992. Observers are lighter (624 against 1504 bytes).', 'Matters only for very large caches; lower gcTime to bound them.', 'performance', 100
  where not exists (select 1 from public.limitations where title = 'Memory per cache entry is higher than TanStack Query');
insert into public.limitations (title, detail, workaround, area, sort) select 'Benchmarks come from one machine', 'All numbers are from a 2-core Xeon on Node 22 and jsdom, and the engine run predates 0.1.0. Treat ratios as indicative.', 'Run pnpm bench on your own hardware; see the benchmarks page.', 'performance', 110
  where not exists (select 1 from public.limitations where title = 'Benchmarks come from one machine');
insert into public.limitations (title, detail, workaround, area, sort) select 'The devtools panel is minimal', 'It lists queries and events and can refetch, invalidate and remove. There is no request timeline.', 'Use createInspector headless and build your own view.', 'devtools', 120
  where not exists (select 1 from public.limitations where title = 'The devtools panel is minimal');
insert into public.limitations (title, detail, workaround, area, sort) select 'The ASP.NET Core fixture is hand-written', 'NestJS output is verified on real @nestjs/swagger output; the ASP.NET sample was written by hand.', 'Run nyx validate on your real document and report anything it rejects.', 'codegen', 130
  where not exists (select 1 from public.limitations where title = 'The ASP.NET Core fixture is hand-written');

