insert into public.issues (title, detail, area, size, sort) select 'Implement useQueries', 'Observe a dynamic list of queries in one hook with per-query results.', 'react', 'medium', 50
  where not exists (select 1 from public.issues where title = 'Implement useQueries');
insert into public.issues (title, detail, area, size, sort) select 'Split generated output per tag', 'An output option that writes one file per OpenAPI tag while keeping imports deterministic.', 'codegen', 'medium', 60
