insert into public.issues (title, detail, area, size, sort) select 'Profile memory per cache entry', 'Find what each entry retains beyond its data and shrink it.', 'performance', 'medium', 80
  where not exists (select 1 from public.issues where title = 'Profile memory per cache entry');
insert into public.issues (title, detail, area, size, sort) select 'Persister API', 'Save and restore the cache through a storage interface, with versioning and a size limit.', 'core', 'large', 90
  where not exists (select 1 from public.issues where title = 'Persister API');
insert into public.issues (title, detail, area, size, sort) select 'Vue adapter', 'Composables over QueryObserver with reactive options.', 'react', 'large', 100
  where not exists (select 1 from public.issues where title = 'Vue adapter');
insert into public.issues (title, detail, area, size, sort) select 'GraphQL subscriptions', 'Generate typed subscription helpers over a pluggable transport.', 'graphql', 'large', 110
